import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            S = next(iterator)
        except StopIteration:
            break

        if len(S) != N:
            pass

        freq = {}
        for c in S:
            freq[c] = freq.get(c, 0) + 1

        odd_count = 0
        for count in freq.values():
            if count % 2 == 1:
                odd_count += 1

        if N % 2 == 0 and odd_count > 0:
            print("NO")
            continue
        elif N % 2 == 1 and odd_count > 1:
            print("NO")
            continue

        print("YES")

        chars = list(S)
        n = len(chars)
        left = 0
        right = n - 1
        ops = 0

        while left < right:
            if chars[left] == chars[right]:
                left += 1
                right -= 1
                continue

            l = left
            r = right

            found_l = -1
            found_r = -1

            for i in range(right, left, -1):
                if chars[i] == chars[left]:
                    found_l = i
                    break

            for i in range(left, right):
                if chars[i] == chars[right]:
                    found_r = i
                    break

            if found_l == -1:
                found_l = None

            if found_r == -1:
                found_r = None

            if found_l is None and found_r is None:
                break

            if found_l is not None and found_r is not None:
                dist_l = found_l - left
                dist_r = right - found_r
                if dist_l <= dist_r:
                    ops += dist_l
                    for i in range(found_l, left, -1):
                        chars[i], chars[i-1] = chars[i-1], chars[i]
                else:
                    ops += dist_r
                    for i in range(found_r, right):
                        chars[i], chars[i+1] = chars[i+1], chars[i]
            elif found_l is not None:
                ops += found_l - left
                for i in range(found_l, left, -1):
                    chars[i], chars[i-1] = chars[i-1], chars[1]
            else:
                ops += right - found_r
                for i in range(found_r, right):
                    chars[i], chars[i+1] = chars[i+1], chars[1]

            left += 1
            right -= 1

        print(ops)

if __name__ == "__main__":
    solve()
